--
-- Stand-in struktur untuk tampilan `vw_dashboard_metrics`
-- (Lihat di bawah untuk tampilan aktual)
--
CREATE TABLE `vw_dashboard_metrics` (
`total_sales` decimal(37,2)
,`pending_orders` bigint(21)
,`active_services` bigint(21)
,`total_products` bigint(21)
,`low_stock_products` bigint(21)
,`total_customers` bigint(21)
,`total_suppliers` bigint(21)
);

