--
-- Struktur untuk view `vw_dashboard_metrics`
--
DROP TABLE IF EXISTS `vw_dashboard_metrics`;

CREATE ALGORITHM=UNDEFINED DEFINER=`root`@`localhost` SQL SECURITY DEFINER VIEW `vw_dashboard_metrics`  AS SELECT (select coalesce(sum(`orders`.`total`),0) from `orders` where `orders`.`status` in ('Sedang Dikirim','Perlu Dikemas','Selesai','Diproses')) AS `total_sales`, (select count(0) from `orders` where `orders`.`status` in ('Perlu Dikemas','Menunggu Bayar','Diproses')) AS `pending_orders`, (select count(0) from `services` where `services`.`stage` not in ('Siap Diambil','Selesai')) AS `active_services`, (select count(0) from `products`) AS `total_products`, (select count(0) from `products` where `products`.`stock` <= 3) AS `low_stock_products`, (select count(0) from `customers`) AS `total_customers`, (select count(0) from `suppliers`) AS `total_suppliers` ;

