INSERT INTO `roles` (`id`, `slug`, `name`, `description`, `default_scope`, `is_system`, `created_at`, `updated_at`) VALUES
('role-audit', 'audit', 'Audit', 'Pengawas kepatuhan (Read Only) audit log, rekam jejak transaksi, dan verifikasi stok.', 'ALL', 1, '2026-09-28 13:08:22', '2026-09-28 13:08:22'),
('role-digital-marketing', 'digital_marketing', 'Digital Marketing', 'Pengelolaan konten promosi, banner, voucher diskon, dan analytics kampanye produk.', 'ALL', 1, '2026-09-28 13:08:22', '2026-09-28 13:08:22'),
('role-finance', 'finance', 'Finance', 'Pengelolaan kas, bank, verifikasi pembayaran, hutang/piutang, biaya, dan laporan keuangan.', 'ALL', 1, '2026-09-28 13:08:22', '2026-09-28 13:08:22'),
('role-gudang', 'gudang', 'Gudang', 'Penerimaan stok, transfer barang, mutasi serial number/IMEI, dan stock opname.', 'STORE', 1, '2026-09-28 13:08:22', '2026-09-28 13:08:22'),
('role-kasir', 'kasir', 'Kasir', 'Operasional POS kasir, scan produk, pembuatan faktur penjualan, dan cetak struk.', 'OWN', 1, '2026-09-28 13:08:22', '2026-09-28 13:08:22'),
('role-kepala-toko', 'kepala_toko', 'Kepala Toko', 'Pimpinan operasional toko cabang spesifik, persetujuan diskon, refund, dan monitoring staf.', 'STORE', 1, '2026-09-28 13:08:22', '2026-09-28 13:08:22'),
('role-manajer-area', 'manajer_area', 'Manager Area', 'Pengawas operasional dan persetujuan transaksi seluruh toko dalam area regional yang ditugaskan.', 'AREA', 1, '2026-09-28 13:08:22', '2026-09-28 13:08:22'),
('role-owner', 'owner', 'Owner', 'Pemilik bisnis dengan akses penuh seluruh dashboard, laporan, dan otorisasi level tinggi.', 'ALL', 1, '2026-09-28 13:08:22', '2026-09-28 13:08:22'),
('role-super-admin', 'super_admin', 'Super Admin', 'Administrator teknis sistem, manajemen pengguna, konfigurasi, cabang, dan master data.', 'ALL', 1, '2026-09-28 13:08:22', '2026-09-28 13:08:22');
